  ('e36054d8-50bc-4974-aa65-000000000058'::uuid, 'استقطاب الضوء', 'زاوية بروستر (زاوية الاستقطاب) هي زاوية السقوط التي:', '["يكون فيها الانعكاس كليًا","تساوي صفرًا","تساوي 90°","تجعل الضوء المنعكس مستقطبًا كليًا والزاوية بين المنعكس والمنكسر قائمة"]'::jsonb, 3, 58),
  ('e36054d8-50bc-4974-aa65-000000000059'::uuid, 'استقطاب الضوء', 'العلاقة بين زاوية بروستر (θp) ومعامل انكسار الوسط (n) هي:', '["sinθp = n","tanθp = n","cosθp = n","θp = n"]'::jsonb, 1, 59),
  ('e36054d8-50bc-4974-aa65-000000000060'::uuid, 'استقطاب الضوء', 'تعتمد زاوية بروستر على:', '["معامل انكسار الوسط","شدة الضوء","سرعة الضوء فقط","لون السطح"]'::jsonb, 0, 60),
  ('e36054d8-50bc-4974-aa65-000000000061'::uuid, 'استقطاب الضوء', 'إذا كانت زاوية السقوط على السطح العاكس تساوي صفرًا:', '["يحصل استقطاب كلي","يحصل استقطاب جزئي كبير","لا يحصل استقطاب","ينعدم الضوء"]'::jsonb, 2, 61),
  ('e36054d8-50bc-4974-aa65-000000000062'::uuid, 'الاستطارة في الضوء', 'الاستطارة هي تشتت الضوء عند سقوطه على:', '["أسطح معدنية ملساء","مادة معتمة","مرآة مستوية","جزيئات الهواء التي أقطارها أصغر أو مساوية للطول الموجي للضوء الساقط"]'::jsonb, 3, 62),
  ('e36054d8-50bc-4974-aa65-000000000063'::uuid, 'الاستطارة في الضوء', 'شدة الضوء المستطار تتناسب مع:', '["1/λ⁴","λ⁴","1/λ","λ"]'::jsonb, 0, 63),
  ('e36054d8-50bc-4974-aa65-000000000064'::uuid, 'الاستطارة في الضوء', 'سبب زرقة السماء هو:', '["انعكاس ضوء البحار","استطارة اللون الأزرق لأن طوله الموجي قصير","استقطاب الضوء","حيود الضوء"]'::jsonb, 1, 64),
  ('e36054d8-50bc-4974-aa65-000000000065'::uuid, 'الاستطارة في الضوء', 'يتلون الأفق بالأحمر والبرتقالي عند الشروق والغروب لأن:', '["الأزرق ينعدم","الشمس تنبعث حمراء","استطارة الأحمر والبرتقالي قليلة لأنهما من الأطوال الموجية الطويلة","الاستقطاب"]'::jsonb, 2, 65),
  ('e36054d8-50bc-4974-aa65-000000000066'::uuid, 'الاستطارة في الضوء', 'خلال النهار يرى رائد الفضاء على سطح القمر السماء سوداء لأن:', '["القمر يمتص الضوء","الشمس تنطفئ","النجوم مستقطبة","لا يوجد غالف جوي يسبب استطارة ضوء الشمس"]'::jsonb, 3, 66),
  ('e36054d8-50bc-4974-aa65-000000000067'::uuid, 'مسائل', 'وُضعت شاشة على بعد 4.5 m من حاجز ذي شقين أضيء بضوء أحادي اللون طوله الموجي 490 nm، فكانت المسافة بين مركز الهدب المركزي المضيء ومركز الهدب المضيء ذي الرتبة (m = 1) تساوي 4.5 cm. البعد بين الشقين يساوي:', '["4.9×10⁻⁴ m","4.9×10⁻⁵ m","4.9×10⁻⁶ m","4.9×10⁻⁷ m"]'::jsonb, 1, 67),
  ('e36054d8-50bc-4974-aa65-000000000068'::uuid, 'مسائل', 'ضوء أبيض تتوزع مركّبات طيفه بواسطة محزز حيود عدد حزوزه 2000 خط/cm. زاوية حيود الرتبة الأولى للضوء الأحمر (λ = 640 nm) تساوي تقريبًا:', '["3.7°","14.7°","7.35°","0.128°"]'::jsonb, 2, 68),
  ('e36054d8-50bc-4974-aa65-000000000069'::uuid, 'مسائل', 'سقطت حزمة ضوئية على سطح عاكس فأصبح الشعاع المنعكس مستقطبًا كليًا عندما كانت زاوية السقوط 48°، حيث (tan 48° = 1.110). معامل انكسار الوسط يساوي:', '["1.110","0.900","48","1.480"]'::jsonb, 0, 69),
  ('e36054d8-50bc-4974-aa65-000000000070'::uuid, 'مسائل', 'إذا كانت الزاوية الحرجة للأشعة الضوئية لمادة العقيق الأزرق المحاطة بالهواء 34.4°، حيث (sin 34.4° = 0.565، tan 60.5° = 1.77)، فإن زاوية الاستقطاب لهذه المادة تساوي:', '["34.4°","60.5°","29.5°","1.77°"]'::jsonb, 1, 70)
)
INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 5, 'البصريات الفيزيائية', s.section, 'ar', s.question, s.choices, s.answer_index,
       'أسئلة اختيار من متعدد - الفصل الخامس: البصريات الفيزيائية', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 5 AND b.language = 'ar' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;